"use strict";

function unavailable() {
  throw new Error("The native koffi binding is unavailable on Android");
}

const koffi = {
  pointer() {
    return {};
  },
  struct(_name, fields) {
    return { size: Object.keys(fields || {}).length };
  },
  array() {
    return {};
  },
  load: unavailable,
  alloc: unavailable,
  decode: unavailable,
  encode: unavailable,
  errno: () => 0,
};

module.exports = koffi;
module.exports.default = koffi;
